def chebyshev_polynomial_t(input, n, *, out=None):
    n_int = int(n.item() if hasattr(n, 'item') else n)
    if n_int == 0:
        result = torch.ones_like(input)
    elif n_int == 1:
        result = input
    else:
        t0, t1 = torch.ones_like(input), input
        for _ in range(1, n_int):
            t0, t1 = t1, 2 * input * t1 - t0
        result = t1
    if out is not None:
        out.copy_(result)
        return out
    return result

